import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    df['Category'] = df['Category'].str.strip()
    df['Category'] = df['Category'].replace({'Furnture': 'Furniture', 'Accesories': 'Accessories'})
    return df

def answer(df):
    df = clean(df)
    return df['Category'].value_counts().to_dict()
